function Toggle({ render }) {
  const [on, setOn] = useState(false);
  const toggle = () => setOn(!on);

  return render({ on, toggle });
}

// Usage
<Toggle>
  {({ on, toggle }) => (
    <div>
      <p>The switch is {on ? 'ON' : 'OFF'}</p>
      <button onClick={toggle}>Toggle</button>
    </div>
  )}
</Toggle>

function FormInput({ name, validate, render }) {
  const [value, setValue] = useState('');
  const [touched, setTouched] = useState(false);

  const error = validate ? validate(value) : null;

  return render({
    name,
    value,
    error: touched ? error : null,
    onChange: (e) => setValue(e.target.value),
    onBlur: () => setTouched(true)
  });
}

// Usage
<FormInput
  name="email"
  validate={(v) => !v.includes('@') ? 'Invalid email' : null}
  render={({ name, value, error, onChange, onBlur }) => (
    <div>
      <input name={name} value={value} onChange={onChange} onBlur={onBlur} />
      {error && <span className="error">{error}</span>}
    </div>
  )}
/>

function CopyToClipboard({ text, render }) {
  const [copied, setCopied] = useState(false);

  const copy = async () => {
    await navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return render({ copied, copy });
}

// Usage
<CopyToClipboard text="Hello World">
  {({ copied, copy }) => (
    <button onClick={copy}>
      {copied ? 'Copied!' : 'Copy'}
    </button>
  )}
</CopyToClipboard>

// React Component Example with Hooks
import React, { useState, useEffect, useCallback } from 'react';

function DataFetcher({ endpoint }) {
  // State management with useState
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // useCallback for memoized fetch function
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(endpoint);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const result = await response.json();
      setData(result);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [endpoint]);

  // useEffect for side effects
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  if (loading) return <div className="loading">Loading...</div>;
  if (error) return <div className="error">Error: {error}</div>;

  return (
    <div className="data-container">
      <h2>Fetched Data</h2>
      <pre>{JSON.stringify(data, null, 2)}</pre>
    </div>
  );
}

export default DataFetcher;

